#include <cstddef>
#include <cstdlib>
#include <cstring>
#include <iostream>

constexpr std::size_t guard{8};

void* guardedAlloc(std::size_t size)
{
    return std::malloc(size);
}

void guardedFree(void* p)
{
    std::free(p);
}

int main()
{
    char* p{static_cast<char*>(guardedAlloc(16))};
    std::memset(p, 'x', 16);
    guardedFree(p);
}
